'use strict';

/**
* Compute the Huber loss.
*
* @module @stdlib/ml/base/loss/float64/huber
*
* @example
* var huber = require( '@stdlib/ml/base/loss/float64/huber' );
*
* var v = huber( 5.0, 10.2, 0.782 );
* // returns 34.59
*
* v = huber( 2.0, 8.0, 0.202 );
* // returns 13.596
*
* v = huber( 1.0, 23.2, -0.999 );
* // returns 23.699
*
* v = huber( 11.0, -12.2, 0.234 );
* // returns 76.274
*
* v = huber( 2.0, -21.0, 0.2 );
* // returns 40.4
*
* v = huber( 9.0, 4.0, -0.9 );
* // returns 12.005
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
